// Blitz Climb — Cloudflare Worker.
// Serves the trainer, a progress API, and a puzzle-set endpoint the weekly job refreshes.
// Bindings: KV namespace PROGRESS ; secret ADMIN_TOKEN (for publishing puzzles).
const APP_B64="";
function appHtml(){const b=atob(APP_B64);const u=Uint8Array.from(b,c=>c.charCodeAt(0));return new TextDecoder().decode(u);}
export default {
  async fetch(req, env){
    const url=new URL(req.url);
    // --- progress: /api/state?u=<code> ---
    if(url.pathname==="/api/state"){
      const u=(url.searchParams.get("u")||"").toLowerCase();
      if(!/^[a-z0-9]{6,64}$/.test(u)) return new Response("bad code",{status:400});
      const key="state:"+u;
      if(req.method==="GET"){const v=await env.PROGRESS.get(key);return v?new Response(v,{headers:{"content-type":"application/json"}}):new Response("",{status:404});}
      if(req.method==="PUT"){const b=await req.text();if(b.length>300000)return new Response("too large",{status:413});await env.PROGRESS.put(key,b);return new Response("ok");}
      return new Response("method not allowed",{status:405});
    }
    // --- live puzzle set (weekly job writes KV "puzzles"); app falls back to embedded ---
    if(url.pathname==="/puzzles.json"){
      const v=await env.PROGRESS.get("puzzles");
      return v?new Response(v,{headers:{"content-type":"application/json"}}):new Response("",{status:404});
    }
    // --- admin: publish a new puzzle set (used by the weekly GitHub Action) ---
    if(url.pathname==="/api/puzzles"&&req.method==="PUT"){
      const tok=req.headers.get("x-admin-token")||url.searchParams.get("key")||"";
      if(!env.ADMIN_TOKEN||tok!==env.ADMIN_TOKEN) return new Response("unauthorized",{status:401});
      const b=await req.text();if(b.length>1500000)return new Response("too large",{status:413});
      try{JSON.parse(b);}catch(e){return new Response("invalid json",{status:400});}
      await env.PROGRESS.put("puzzles",b);return new Response("ok");
    }
    // --- everything else: the app ---
    return new Response(appHtml(),{headers:{"content-type":"text/html; charset=utf-8"}});
  }
};
